(function(){'use strict';
const t=(ar,en)=>document.documentElement.lang==='en'?en:ar,esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const scope=()=>window.MiyarEnterprise?.session?.()?.scope||'local';
const key=()=> 'miyar-salary-bands-v1:'+scope();
function readBands(){try{return JSON.parse(localStorage.getItem(key())||'[]');}catch{return[];}}
function parseBands(text){
 const rows=window.MiyarEnterpriseCore.csv(text),required=['grade','min','mid','max','currency','period','source','effectiveDate'];
 if(!rows.length||rows.length>500)throw Error(t('استورد من 1 إلى 500 نطاق.','Import 1–500 bands.'));
 const seen=new Set();return rows.map((r,i)=>{if(required.some(k=>!String(r[k]||'').trim())||Object.keys(r).some(k=>!required.includes(k)))throw Error(t('راجع الأعمدة المطلوبة في الصف ','Check required columns in row ')+(i+2));
 const nums=['min','mid','max'].map(k=>Number(r[k])),id=r.grade+'|'+r.effectiveDate;
 if(nums.some(n=>!Number.isFinite(n)||n<0)||!(nums[0]<nums[1]&&nums[1]<nums[2])||!['monthly','annual'].includes(r.period)||! /^[A-Z]{3}$/.test(r.currency)||!/^\d{4}-\d{2}-\d{2}$/.test(r.effectiveDate)||Number.isNaN(Date.parse(r.effectiveDate))||new Date(r.effectiveDate).toISOString().slice(0,10)!==r.effectiveDate||seen.has(id)||r.grade.length>100||r.source.length>500)throw Error(t('نطاق غير صالح أو مكرر في الصف ','Invalid or duplicate band in row ')+(i+2));
 seen.add(id);return {...r,min:nums[0],mid:nums[1],max:nums[2]};});
}
function bandFor(grade,rows=readBands(),date=new Date().toISOString().slice(0,10)){return rows.filter(r=>r.grade===grade&&r.effectiveDate<=date).sort((a,b)=>b.effectiveDate.localeCompare(a.effectiveDate))[0]||null;}
function applyBand(grade){const b=bandFor(grade),status=document.getElementById('audit-band-status');if(!b){if(status)status.textContent=t('لا يوجد نطاق نافذ لهذه الدرجة. استورد ملف الجهة أو أدخل النطاق ومصدره.','No effective band for this grade. Import organization bands or enter a band and source.');return;}
 for(const [id,value]of Object.entries({grade:b.grade,min:b.min,mid:b.mid,max:b.max,currency:b.currency,period:b.period,source:b.source+' · '+b.effectiveDate})){const el=document.getElementById('cp-'+id);if(el){el.value=value;el.dispatchEvent(new Event('input',{bubbles:true}));}}if(status)status.textContent=t('طُبق نطاق الجهة النافذ بتاريخ ','Applied organization band effective ')+b.effectiveDate;
}
function salaryImport(){const page=document.querySelector('.cp-page');if(!page||page.querySelector('[data-audit-bands]'))return;
 const box=document.createElement('details');box.dataset.auditBands='';box.className='audit-panel';box.innerHTML='<summary>'+t('استيراد نطاقات الرواتب من CSV','Import salary bands from CSV')+'</summary><p>'+t('يُحفظ الملف في مساحة هذا المتصفح فقط. لا يمثل اعتمادًا مؤسسيًا أو بيانات سوق. الأعمدة المطلوبة:','Saved only in this browser workspace. This is not organization approval or market data. Required columns:')+'</p><code dir="ltr">grade,min,mid,max,currency,period,source,effectiveDate</code><p>'+t('الفترة monthly أو annual، والتاريخ YYYY-MM-DD. الدرجة مطابقة حرفيًا لدرجة التقييم.','Period: monthly or annual. Date: YYYY-MM-DD. Grade must exactly match the evaluation grade.')+'</p><label>'+t('ملف CSV (حتى 250 كيلوبايت)','CSV file (up to 250 KB)')+'<input type="file" accept=".csv,text/csv" data-band-file></label><div data-band-preview></div><p id="audit-band-status" role="status" aria-live="polite"></p><button type="button" data-band-apply>'+t('تطبيق النطاق النافذ للدرجة الحالية','Apply effective band for current grade')+'</button>';
 page.querySelector('.cp-heading').insertAdjacentElement('afterend',box);
 const status=box.querySelector('#audit-band-status'),preview=box.querySelector('[data-band-preview]');box.querySelector('[data-band-file]').onchange=async e=>{preview.innerHTML='';try{const file=e.target.files[0];if(!file)return;if(file.size>250000)throw Error(t('الملف أكبر من 250 كيلوبايت.','File exceeds 250 KB.'));const captured=scope(),rows=parseBands(await file.text());if(captured!==scope())return;preview.innerHTML='<p>'+t('نطاقات جاهزة للمعاينة: ','Bands ready for preview: ')+rows.length+'</p><div class="ent-table-wrap"><table><thead><tr>'+['Grade','Min','Mid','Max','Currency','Period','Source','Effective date'].map(h=>'<th scope="col">'+h+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+['grade','min','mid','max','currency','period','source','effectiveDate'].map(k=>'<td>'+esc(r[k])+'</td>').join('')+'</tr>').join('')+'</tbody></table></div><button type="button" data-band-save>'+t('حفظ هذه القائمة بدل القائمة المحلية السابقة','Replace the previous local list with this list')+'</button>';preview.querySelector('button').onclick=()=>{if(captured!==scope())return;try{localStorage.setItem(key(),JSON.stringify(rows));status.textContent=t('حُفظت النطاقات محليًا.','Bands saved locally.');preview.innerHTML='';applyBand(document.getElementById('cp-grade').value.trim());}catch{status.textContent=t('تعذر الحفظ في المتصفح.','Browser storage is unavailable.');}};}catch(err){status.textContent=err.message;}};
 box.querySelector('[data-band-apply]').onclick=()=>applyBand(document.getElementById('cp-grade').value.trim());
 try{const handoff=JSON.parse(sessionStorage.getItem('miyar-grade-handoff')||'null');if(handoff&&handoff.scope===scope()){document.getElementById('cp-grade').value=handoff.grade;document.getElementById('cp-role').value=handoff.role;applyBand(handoff.grade);sessionStorage.removeItem('miyar-grade-handoff');}}catch{}
}
function decorate(){
 document.querySelectorAll('.lp-footer .lp-wrap,.main-footer,.sidebar-footer').forEach(footer=>{if(footer.querySelector('[data-trust-links]'))return;const links=document.createElement('span');links.dataset.trustLinks='';links.className='audit-links';links.innerHTML=[['privacy',t('الخصوصية','Privacy')],['methodology',t('المنهجية','Methodology')],['status',t('حالة الخدمات','Service status')],['changes',t('التحديثات','Changes')]].map(([id,label])=>'<a href="./trust.html#'+id+'">'+label+'</a>').join('');footer.append(links);});
 document.querySelectorAll('thead th:not([scope])').forEach(el=>el.setAttribute('scope','col'));
 document.querySelectorAll('#demo-status,#ent-flash,#demo-runtime-status,#guided-start-status').forEach(el=>{if(!el.hasAttribute('aria-live')){el.setAttribute('aria-live','polite');el.setAttribute('role','status');}});
 const login=document.getElementById('ent-login');if(login&&!document.getElementById('audit-recovery-help')){const p=document.createElement('p');p.id='audit-recovery-help';p.innerHTML='<a href="./trust.html#recovery">'+t('نسيت كلمة المرور؟ اطلب رابط استعادة من مسؤول جهتك.','Forgot your password? Ask your organization administrator for a recovery link.')+'</a>';login.insertAdjacentElement('afterend',p);}
 if(location.hash==='#enterprise/grading'){const content=document.getElementById('ent-content');if(content&&!content.querySelector('[data-framework-help]')){const p=document.createElement('p');p.dataset.frameworkHelp='';p.innerHTML='<a href="#enterprise/connection">'+t('استيراد إطار تقييم الجهة: الحساب والإعدادات ← دخول المسؤول ← معاينة إطار JSON وتفعيله','Import your evaluation framework: Account & settings → administrator sign-in → preview and activate framework JSON')+'</a>';content.prepend(p);}}
 const nav=document.querySelector('.sidebar nav.nav-list');if(nav){for(const [id,selector,ar,en]of [['decide','[data-strategy-nav]','اتخذ القرار','Decide'],['design','[data-od-nav]','صمّم','Design'],['plan','[data-manpower-nav]','خطط وعوّض','Plan & pay'],['operate','[data-enterprise-open="overview"]','شغّل وتابع','Operate']]){const target=nav.querySelector(selector);if(target&&!nav.querySelector('[data-audit-group="'+id+'"]')){const label=document.createElement('div');label.className='nav-group-label';label.dataset.auditGroup=id;label.textContent=t(ar,en);target.insertAdjacentElement('beforebegin',label);}}}
 salaryImport();
}
window.addEventListener('miyar:grade-calculated',event=>{const d=event.detail;if(!d?.grade)return;try{sessionStorage.setItem('miyar-grade-handoff',JSON.stringify({...d,scope:scope()}));}catch{}setTimeout(()=>{const target=document.getElementById('ent-grade-result');if(!target||target.querySelector('[data-grade-pay]'))return;const a=document.createElement('a');a.dataset.gradePay='';a.className='button button-outline';a.href='#enterprise/compensation';a.textContent=t('استخدام الدرجة في التعويضات','Use grade in compensation');target.append(a);},0);});
let queued=false;function schedule(){if(queued)return;queued=true;setTimeout(()=>{queued=false;decorate();},0);}new MutationObserver(schedule).observe(document.documentElement,{childList:true,subtree:true});window.addEventListener('hashchange',schedule);window.addEventListener('miyar:session',()=>{document.querySelector('[data-audit-bands]')?.remove();schedule();});schedule();
window.MiyarSalaryBands={parse:parseBands,select:bandFor};
})();
